function slaTab(){const open=ALLI().filter(isOpen).map(i=>slaOf(i)),br=open.filter(s=>s.breach).length,rk=open.filter(s=>s.risk&&!s.breach).length;
if(!S.bt.itsm_slat)S.bt.itsm_slat={q:"",sort:{k:"reso",d:1},f:{st:["New","In progress","On hold"]},group:undefined};
const cols=incCols().filter(c=>["id","pri","svc","grp","own","resp","reso","st"].includes(c.k));
return `<div class="itsm-stack"><div class="statrow"><div class="stat ${br?"crit":""}"><small>Breached</small><span class="num" data-role="metric">${N0(br)}</span><em>past target, act now</em></div><div class="stat"><small>At risk</small><span class="num" data-role="metric">${N0(rk)}</span><em>under 25% of target left</em></div><div class="stat"><small>On track</small><span class="num" data-role="metric">${N0(open.length-br-rk)}</span><em>plenty of time</em></div><div class="stat"><small>SLA compliance</small><span class="num" data-role="metric">${MV().m_itsm_sla.cur}%</span><em>30 days ${fchip("m_itsm_sla")}</em></div></div>
<p class="muted small" data-role="story">Clocks pause while an incident waits on a caller, vendor or change. Sort by Resolution to see what breaches first. ${stdChip("xla","Alongside SLA clocks we will add experience level agreements: how the caller felt about the fix, not only how fast.")}</p>${btHTML({id:"itsm_slat",cols,rows:()=>ALLI(),key:"id",h:480,rowH:42,facets:["pri","st","grp"],exportName:"sla-clocks",open:id=>incDrawer(id)})}</div>`}


