function miUpd(){openForm({id:"itsm_miup",title:"Add a timeline entry",story:"Every decision and finding goes on the timeline while it is fresh. The post-incident review is built from this record.",submit:"Add entry",defaults:{kind:"Update",who:X.mi.roles.scribe&&!!who(X.mi.roles.scribe)?X.mi.roles.scribe:X.mi.roles.ic},fields:[{k:"kind",label:"Kind",type:"chips",opts:["Update","Finding","Hypothesis","Decision","Action","Comms"]},{k:"who",label:"Who",type:"people",req:true},{k:"x",label:"What happened",type:"longtext",req:true,wide:true}],onSubmit:v=>{X.mi.tl.push([0,v.who,v.kind,v.x]);done("Timeline entry",v.kind+" · "+v.x.slice(0,40))}})}
