function sendComm(id){const c=X.mi.comms.find(x=>x.id===id),cm=X.mi.roles.comms;if(!cm){toast("Assign a communications lead first: drag a person into the role in the War room tab","warn");return}c.st="Sent";c.at=hmAt(0);c.by=cm;X.mi.tl.push([0,cm,"Comms","Update sent to "+c.aud+" ("+c.chan+")."]);done("Update approved and sent",c.aud+" · approved by "+cm)}
function pirForm(){const m=X.mi,inc=INC(m.inc),p=m.pir||{};const defs=Object.assign(CO()?{title:"Post-incident review: "+(inc?inc.id+" "+inc.t:""),users:140,det:"Monitoring",ok:"Fast declaration, clear roles, emergency change approved in under 20 minutes.",bad:"Capacity was not tied to editor growth. No alert on connection saturation. Comms lead was unassigned for 4 hours.",create:true,w1:PRB("PRB0010").why[0],w2:PRB("PRB0010").why[1],w3:PRB("PRB0010").why[2],w4:PRB("PRB0010").why[3],w5:PRB("PRB0010").why[4],a1t:"Add an alert on database connection saturation at 80%",a1o:"Tom Becker",a1d:"2026-10-13",a2t:"Add an autoscale rule to the web tier (part of CHG0312)",a2o:"Sam Patel",a2d:"2026-10-20",a3t:"Add a capacity review to the project gate for beta releases",a3o:"Maya Ortiz",a3d:"2026-10-30"}:{title:"Post-incident review: "+(inc?inc.id+" "+inc.t:""),det:"Monitoring",create:true},p);
openForm({id:"itsm_pir",title:"Post-incident review",story:"A blameless review: what happened, why, and what we will change. Action items become tasks with an owner and a date, so the review ends in work, not a document.",submit:"Save review and create tasks",defaults:defs,
fields:[{section:"Summary"},{k:"title",label:"Title",type:"text",req:true,wide:true},{k:"users",label:"People affected",type:"number",min:0},{k:"det",label:"How was it detected",type:"chips",opts:["Monitoring","User report","Vendor"]},{k:"sum",label:"Summary",type:"longtext",req:true,wide:true,ai:{label:"Draft from timeline",fn:()=>"Between "+hmAt(m.start)+" and "+(m.restored!=null?hmAt(m.restored):"now")+" ("+fH(miEl())+"), "+(inc?inc.svc:"the service")+" was degraded for "+(defs.users||(CO()?140:0))+" people."+(CO()?" The cause was probable capacity saturation of the hosting tier. Emergency change CHG0311 scaled the web tier.":"")}},
{section:"Why it happened: five whys"},...[1,2,3,4,5].map(n=>({k:"w"+n,label:"Why "+n,type:"text"})),{k:"ok",label:"What went well",type:"longtext",wide:true},{k:"bad",label:"What to improve",type:"longtext",wide:true},
{section:"Action items become tasks"},...[1,2,3].flatMap(n=>[{k:"a"+n+"t",label:"Action "+n,type:"text",wide:true,req:n===1},{k:"a"+n+"o",label:"Owner",type:"people"},{k:"a"+n+"d",label:"Due",type:"date"}]),{k:"create",label:"Create tasks from the actions",type:"toggle"}],
onSubmit:v=>{m.pir={title:v.title,users:v.users,det:v.det,sum:v.sum||"",why:[1,2,3,4,5].map(n=>v["w"+n]||""),ok:v.ok,bad:v.bad,saved:U.fmtDate(U.todayDate())};Object.assign(m.pir,{a1t:v.a1t,a1o:v.a1o,a1d:v.a1d,a2t:v.a2t,a2o:v.a2o,a2d:v.a2d,a3t:v.a3t,a3o:v.a3o,a3d:v.a3d,create:v.create,users:v.users,det:v.det,sum:v.sum||"",ok:v.ok,bad:v.bad,w1:v.w1,w2:v.w2,w3:v.w3,w4:v.w4,w5:v.w5});let n=0;
if(v.create)[1,2,3].forEach(k=>{if(v["a"+k+"t"]&&!X.tasks.find(t=>t.t===v["a"+k+"t"])){X.tasks.push({id:"T-"+X.seq.t++,t:v["a"+k+"t"],who:v["a"+k+"o"]||(CO()?"Tom Becker":ME()),due:v["a"+k+"d"]||addD(TODAYI,14),from:"PIR "+m.inc,done:false});n++}});
done("Review saved",n+" task"+(n===1?"":"s")+" created");S.v.itsm_mi=3;render();return {toast:"Review saved and "+n+" new task"+(n===1?"":"s")+" created"}}})}
const AS=()=>DIR.filter(d=>d.kind==="human").map(d=>d.name),AS0=AS(),ASSIGN=()=>CO()?AS0:AS();
